package generic

func Identity[T any](val T) T {
    return val
}

package generic

func Equal[T comparable](a, b T) bool {
    return a == b
}

package generic

func Pair[T, U any](first T, second U) (T, U) {
    return first, second
}

package generic

type Set[T comparable] struct {
    items map[T]struct{}
}

func (s *Set[T]) Add(item T) {
    if s.items == nil {
        s.items = make(map[T]struct{})
    }
    s.items[item] = struct{}{}
}

package generic

func Max[T int64 | float64](a, b T) T {
    if a > b {
        return a
    }
    return b
}

package generic

func Double[T ~int](val T) T {
    return val * 2
}

package generic

import "errors"

func Find[T comparable](slice []T, target T) (int, error) {
    for i, v := range slice {
        if v == target {
            return i, nil
        }
    }
    return -1, errors.New("not found")
}

